response.output:
{
  "world_id": "wld_ghost_ship_meridian",
  "name": "The Meridian Pale",
  "description": "A stretch of cold, windless ocean where a perpetual fog bank hides the SS Meridian Aurelia, a luxury liner that vanished decades ago during its gala maiden crossing. A salvage crew boards the hulk expecting an empty wreck. Instead they find a ship that is still running its final evening: lamps burn, a string quartet tunes in an unseen ballroom, and the dinner service is never allowed to finish. The tone is oppressive. Corridors feel too narrow, the air is thick with brine and old perfume, and the sky never brightens past a bruised grey. The ship does not hunt its visitors. It tries to seat them, and anyone who accepts a place at the table slowly becomes part of the manifest.",
  "locations": [
    {
      "id": "loc_grand_saloon",
      "name": "The Grand Saloon",
      "description": "A vast, chandeliered dining hall where long tables are permanently laid for a banquet. Candles burn without melting, and place cards appear overnight bearing the names of the salvage crew. Fog seeps in under the great doors and pools around the ankles of the seated dead."
    },
    {
      "id": "loc_lower_boiler_decks",
      "name": "The Lower Boiler Decks",
      "description": "A claustrophobic maze of rusted catwalks and cold furnaces beneath the waterline. The engines are dead, yet the pipes tick and groan in a rhythm that matches a dinner bell rung far above. Thick fog gathers here, and crew members who get lost find that the stairways lead only back to the saloon."
    }
  ],
  "factions": [
    {
      "id": "fac_salvage_crew",
      "name": "The Tern Salvage Crew",
      "description": "A debt-ridden team of six salvagers aboard the tug Tern. They came for the liner's rumored strongroom and have no idea the ship is counting them as passengers.",
      "location_ids": ["loc_grand_saloon", "loc_lower_boiler_decks"]
    },
    {
      "id": "fac_remainders",
      "name": "The Remainders",
      "description": "The original passengers and staff, frozen in the last evening of the voyage. They are polite, hospitable and relentless, and each wants a living guest to take their place so they can finally leave the table.",
      "location_ids": ["loc_grand_saloon"]
    },
    {
      "id": "fac_stokers_of_the_deep",
      "name": "The Stokers of the Deep",
      "description": "Engine-room crew who refused to take part in the banquet and now hide below. They know the ship's rules and will trade that knowledge for a promise that the liner will be sunk for good.",
      "location_ids": ["loc_lower_boiler_decks"]
    }
  ],
  "rules": [
    {
      "id": "rul_fog_sustains_ship",
      "statement": "The Meridian Aurelia exists only while the fog surrounds it; thinning fog makes parts of the ship flicker and fade.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_clear_sky",
      "statement": "The sky above the ship never rises above a dim, sunless grey, and no natural light source can burn off the gloom.",
      "category": "physics"
    },
    {
      "id": "rul_place_cards",
      "statement": "Anyone who sits at a place card bearing their own name is added to the ship's manifest and slowly loses memory of life before the voyage.",
      "category": "metaphysics"
    },
    {
      "id": "rul_dinner_bell",
      "statement": "When the dinner bell sounds, every Remainder must walk to the Grand Saloon and cannot be diverted until the bell stops.",
      "category": "social"
    },
    {
      "id": "rul_dead_machinery",
      "statement": "Electronic equipment brought aboard fails within hours, while the liner's own century-old lamps and telephones keep working.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_maiden_gala",
      "name": "The Maiden Gala",
      "description": "On the first night at sea, the owner held a lavish banquet and ordered the doors sealed so no guest would leave before the toast.",
      "era": "Maiden voyage",
      "location_ids": ["loc_grand_saloon"]
    },
    {
      "id": "evt_fog_swallows_liner",
      "name": "The Fog Swallows the Liner",
      "description": "A fog bank rolled in mid-banquet and the ship vanished from all charts and radio logs, leaving the owner's toast unfinished.",
      "era": "Night of the disappearance",
      "location_ids": ["loc_grand_saloon", "loc_lower_boiler_decks"]
    },
    {
      "id": "evt_stokers_walkout",
      "name": "The Stokers' Walkout",
      "description": "The engine crew abandoned their posts and barricaded the lower decks, refusing the summons of the bell and escaping the fate of the dining guests.",
      "era": "Night of the disappearance",
      "location_ids": ["loc_lower_boiler_decks"]
    },
    {
      "id": "evt_failed_salvage",
      "name": "The Failed Salvage of the Orrin",
      "description": "Years ago a previous salvage vessel found the liner. Its crew's names now appear on the manifest, though the vessel was never seen again.",
      "era": "Decades after the vanishing",
      "location_ids": ["loc_grand_saloon"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_seat_or_sink",
      "name": "Seat or Sink",
      "description": "The Remainders want the salvage crew to take their seats so they can be released, while the Stokers of the Deep want the ship scuttled and every Remainder laid to rest. The Tern crew must choose a side before the next bell.",
      "faction_ids": ["fac_remainders", "fac_stokers_of_the_deep", "fac_salvage_crew"]
    },
    {
      "id": "cnf_greed_versus_survival",
      "name": "Greed Versus Survival",
      "description": "Some of the salvage crew will not leave without the strongroom's fortune, while others see that every hour aboard brings them closer to the manifest.",
      "faction_ids": ["fac_salvage_crew"]
    }
  ]
}

