response.output:
{
  "world_id": "wld_empire_of_ashes",
  "name": "Cinerath, the Ash-Crowned City",
  "description": "Cinerath is a walled city-state on a volcanic coast, heir to a fallen empire in the long dusk of late antiquity. Its marble forums are streaked grey with ash from the mountain Vessar, and its people live by grain dole, mercenary garrisons and fading law. The Senate still meets, but it has become a chamber of exhausted families. Into that weakness steps Corvan Idrel, a populist demagogue who promises bread, vengeance and the burning of the old order. Against him stands Aurelian Maro, a disgraced senator stripped of his curule chair. He schemes in the shadows to stop Idrel, knowing that saving the republic may mean committing the same crimes he condemns. The tone is somber: victories cost something, memory is fragile, and every ally carries a private debt. The genre is historical-inspired fiction, with no magic and no firearms, only steel, oil-fire, rhetoric and ledgers. Law here is literally written in ash. When a citizen is condemned, the Ash Archive burns his records and his name is struck from public memory, so the city's politics are shaped by the fear of being erased.",
  "locations": [
    {
      "id": "loc_senate_hall_of_cinerath",
      "name": "The Hall of the Grey Senate",
      "description": "A colonnaded chamber on the Capitoline Terrace, where three hundred senators meet beneath a soot-darkened dome. Its benches are carved with the names of families long since erased, and the seat of the disgraced Aurelian Maro stands conspicuously empty."
    },
    {
      "id": "loc_ash_archive",
      "name": "The Ash Archive",
      "description": "A fireproof vaulted library cut into the mountainside, where clay-tablet records of citizenship, debt and law are kept. Condemned citizens' tablets are burned in its great kiln, and the ash is sealed in urns along the walls."
    },
    {
      "id": "loc_forum_of_dole",
      "name": "The Forum of the Dole",
      "description": "The vast public square where grain is distributed each new moon. Corvan Idrel holds his rallies here, standing on the steps of a toppled imperial statue before crowds that grow every month."
    },
    {
      "id": "loc_salt_harbor",
      "name": "Salt Harbor",
      "description": "A crowded port of grain barges, smugglers and exiled merchants. Its tavern-cellars host the secret meetings of those who still trust coin more than speeches."
    },
    {
      "id": "loc_vessar_terraces",
      "name": "The Vessar Terraces",
      "description": "Vineyards and obsidian quarries climbing the slopes of the restless mountain. Aurelian Maro's confiscated family estate lies here, and the quarry-workers who live beside it are fiercely loyal to Idrel."
    }
  ],
  "factions": [
    {
      "id": "fac_grey_senate",
      "name": "The Grey Senate",
      "description": "The aging aristocratic body that still holds legal authority in Cinerath. It is divided between those who would appease the mob and those who would crush it.",
      "location_ids": ["loc_senate_hall_of_cinerath", "loc_vessar_terraces"]
    },
    {
      "id": "fac_idrelites",
      "name": "The Idrelites",
      "description": "A mass movement of dole-dependent citizens, quarrymen and discharged soldiers who follow Corvan Idrel. They demand the burning of senatorial debts and the opening of the Ash Archive.",
      "location_ids": ["loc_forum_of_dole", "loc_vessar_terraces"]
    },
    {
      "id": "fac_keepers_of_urns",
      "name": "The Keepers of Urns",
      "description": "A secretive priestly-clerical order that tends the Ash Archive and carries out its condemnations. They claim neutrality, but whoever controls the kiln controls who may be remembered.",
      "location_ids": ["loc_ash_archive"]
    },
    {
      "id": "fac_harbor_syndics",
      "name": "The Harbor Syndics",
      "description": "A guild of grain-factors, shipowners and smugglers who control Cinerath's food supply. They sell loyalty to whichever side guarantees their cargoes.",
      "location_ids": ["loc_salt_harbor"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_firearms",
      "statement": "Warfare relies on steel, siege engines, bows and oil-fire; no explosive propellants or firearms exist anywhere in the known world.",
      "category": "technology"
    },
    {
      "id": "rul_senate_required_for_law",
      "statement": "No law, war levy or condemnation is valid unless a quorum of the senate votes for it, and even a demagogue must either win that vote or subvert it.",
      "category": "social"
    },
    {
      "id": "rul_burning_erases_name",
      "statement": "When the Ash Archive burns a citizen's tablets, that person loses all legal standing, property and public mention; speaking the erased name in a public forum is itself a crime.",
      "category": "social"
    },
    {
      "id": "rul_no_magic",
      "statement": "There is no magic; omens and the mountain's tremors are interpreted by priests but have only natural causes.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ashfall_seasons",
      "statement": "Vessar exhales heavy ashfall every autumn, ruining harvests and travel for weeks, so grain imports by sea are essential to the city's survival.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_fall_of_the_throne",
      "name": "The Fall of the Distant Throne",
      "description": "The emperor's court abandoned the western provinces, leaving Cinerath to govern itself under its ancient senate and a ring of unpaid mercenary garrisons.",
      "era": "The Dusk Century",
      "location_ids": ["loc_senate_hall_of_cinerath"]
    },
    {
      "id": "evt_great_ashfall",
      "name": "The Great Ashfall",
      "description": "A catastrophic eruption of Vessar buried the lower terraces and starved thousands, giving birth to the grain dole and the city's lasting dependence on the Harbor Syndics.",
      "era": "The Dusk Century",
      "location_ids": ["loc_vessar_terraces", "loc_salt_harbor"]
    },
    {
      "id": "evt_burning_of_the_maro_tablets",
      "name": "The Burning of the Maro Tablets",
      "description": "Aurelian Maro was accused of embezzling relief funds. The Keepers of Urns burned his family's records, stripping the House of Maro of its name, though Maro insists the charge was forged to silence his opposition to Idrel's patrons.",
      "era": "The Year of Soot",
      "location_ids": ["loc_ash_archive", "loc_senate_hall_of_cinerath"]
    },
    {
      "id": "evt_first_dole_riot",
      "name": "The First Dole Riot",
      "description": "Corvan Idrel rose to prominence when he led starving crowds against the grain stores, forcing the senate to double the distribution.",
      "era": "The Year of Soot",
      "location_ids": ["loc_forum_of_dole"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_senate_versus_idrel",
      "name": "The Struggle for the Forum",
      "description": "Idrel's mass movement seeks to bypass the senate and seize the Ash Archive. The senate is split between appeasement and a coup, and Maro schemes to unite its factions before the mob moves.",
      "faction_ids": ["fac_grey_senate", "fac_idrelites"]
    },
    {
      "id": "cnf_who_controls_memory",
      "name": "The War over the Kiln",
      "description": "The Keepers of Urns are courted by both sides, since condemning an enemy's records would erase him. The Harbor Syndics threaten to starve whichever side moves against the archive first.",
      "faction_ids": ["fac_keepers_of_urns", "fac_harbor_syndics", "fac_idrelites"]
    }
  ]
}

