  "world_id": "wld_the_plain_crown",
  "name": "The Plain Crown",
  "description": "The kingdom of Veyrhollow has prospered for two centuries on one creed: no one may wield, trade, or even speak of arcane power. Its granaries are full, its roads are straight, and its courts are quick. Beneath that order lies a secret the Crown has worked hard to bury. The great boundary wards that keep the old horrors out were never dismantled, because the realm cannot survive without them. They are fed in secret by a hidden class of gifted children, the Quiet Wardens, who are taken from their families and sealed in a cairn. Now the wards are failing, the Wardens are dying faster than they can be replaced, and the people who were taught to fear anything uncanny must decide whether to confess the Crown's hypocrisy or let the borders fall. The tone is grim: prosperity is bought with hidden suffering, and every honest choice costs someone dearly.",
  "locations": [
    {
      "id": "loc_greywick",
      "name": "Greywick",
      "description": "The orderly capital, built of identical grey brick. Citizens carry stamped ledgers of their own conduct, and informants are paid by the pound of evidence. The Assize sits here, and the largest grain exchange in the realm lies at the heart of the city."
    },
    {
      "id": "loc_cairn_of_quiet",
      "name": "The Cairn of Quiet",
      "description": "A windowless stone dormitory on a barren ridge, officially a leper hospice. It houses the Quiet Wardens, whose gifts keep the realm's boundary wards alive. The walls are lined with lead and wool to muffle sound, because the Wardens' dreams leak into the wards."
    },
    {
      "id": "loc_tithe_road",
      "name": "The Tithe Road",
      "description": "A long paved highway of toll houses and grain carts running from Greywick to the frontier. Along its verge stand the old ward-stones, each cracked and weeping black resin as the protection fades."
    },
    {
      "id": "loc_ashfen",
      "name": "Ashfen",
      "description": "A drowned frontier marsh where the wards have already thinned. Strange fog and wrong-shaped animals drift in from beyond the border. Hedge-folk live here in defiance of the law, treating the unexplained quietly and not reporting it."
    }
  ],
  "factions": [
    {
      "id": "fac_plain_assize",
      "name": "The Plain Assize",
      "description": "The Crown's inquisitorial courts, sworn to root out any trace of arcane practice. Most of them sincerely do not know that the wards depend on forbidden talent. Their leaders do know.",
      "location_ids": ["loc_greywick", "loc_tithe_road"]
    },
    {
      "id": "fac_quiet_wardens",
      "name": "The Quiet Wardens",
      "description": "Gifted children and young adults confined in the Cairn, sustaining the wards with their own lives. They speak in a private sign language and have begun to organize a quiet refusal.",
      "location_ids": ["loc_cairn_of_quiet"]
    },
    {
      "id": "fac_ashfen_hedge_folk",
      "name": "The Ashfen Hedge-Folk",
      "description": "Marsh villagers who survive by bargaining with what crosses the thinning border. They shelter fugitive gifted children and hold the only unofficial knowledge of how the wards work.",
      "location_ids": ["loc_ashfen", "loc_tithe_road"]
    }
  ],
  "rules": [
    {
      "id": "rul_ward_cost",
      "statement": "Every boundary ward draws its strength from a living gifted person; when a Warden dies, the ward they sustained weakens until replaced.",
      "category": "metaphysics"
    },
    {
      "id": "rul_arcane_ban",
      "statement": "Possessing, using, or concealing arcane talent is a capital crime, and the Crown denies that talent exists at all.",
      "category": "social"
    },
    {
      "id": "rul_lead_muffling",
      "statement": "Lead and wool dull the output of the gifted, so every Warden is housed behind them to keep their dreams from distorting the wards.",
      "category": "physics"
    },
    {
      "id": "rul_ledger_citizenry",
      "statement": "No citizen may travel, trade, or marry without a stamped ledger of conduct, which makes concealment difficult and informing profitable.",
      "category": "technology"
    },
    {
      "id": "rul_fog_crossing",
      "statement": "Where a ward has failed, the border fog thickens and unnatural creatures can pass through, but only at dusk.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_the_burning_decade",
      "name": "The Burning Decade",
      "description": "After a sorcerer-king's tyranny ended in famine, the first Plain Crown purged every practitioner it could find and outlawed arcane power forever.",
      "era": "Year 1 of the Plain Crown",
      "location_ids": ["loc_greywick"]
    },
    {
      "id": "evt_raising_of_wards",
      "name": "The Secret Raising of the Wards",
      "description": "Terrified of invasion, the founding council secretly kept a handful of gifted prisoners to raise boundary wards, then erased all records of how it was done.",
      "era": "Year 4 of the Plain Crown",
      "location_ids": ["loc_tithe_road"]
    },
    {
      "id": "evt_cairn_founded",
      "name": "Founding of the Cairn of Quiet",
      "description": "The Assize built the Cairn as a hospice cover for the growing number of gifted children sealed in to feed the wards.",
      "era": "Year 62 of the Plain Crown",
      "location_ids": ["loc_cairn_of_quiet"]
    },
    {
      "id": "evt_ashfen_breach",
      "name": "The Ashfen Breach",
      "description": "The first ward collapsed outright in the marsh. The Assize denied it, burned the nearest records, and told the hedge-folk the fog was ordinary weather.",
      "era": "Year 198 of the Plain Crown",
      "location_ids": ["loc_ashfen"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_the_hidden_toll",
      "name": "The Hidden Toll",
      "description": "The Plain Assize must keep feeding children to the wards to preserve the realm's peace, while the Quiet Wardens begin to refuse, threatening the border and the Crown's story of itself.",
      "faction_ids": ["fac_plain_assize", "fac_quiet_wardens"]
    },
    {
      "id": "cnf_marsh_sanctuary",
      "name": "The Marsh Sanctuary",
      "description": "The Ashfen Hedge-Folk hide runaway gifted children and know how to mend the wards without killing anyone, but the Assize hunts them as criminals and will burn Ashfen before conceding the truth.",
      "faction_ids": ["fac_plain_assize", "fac_ashfen_hedge_folk"]
    }
  ]
}

response.output:
{
  "world_id": "wld_ashen_crowns",
  "name": "Verrandor, the Thrice-Crowned Realm",
  "description": "Verrandor is a fractured continent where three royal houses, Calderhal, Mireveil and Orrowyn, each claim the Ember Throne after the last monarch died without a named heir. The war between them is fought with sworn blades, siege-engines of oak and iron, and bargains with the dead. Far to the north, under the Glasswound glacier, an ancient enemy called the Hollow Choir is stirring. Its song makes ice grow where no frost should be. The tone is epic: sweeping marches, doomed oaths, and a realm that must decide whether a crown is worth more than its survival. A distinctive twist is that every crown in Verrandor is forged from a monarch's own bones and remembers its wearers, so a throne can be won by arms but is only held by the consent of the dead.",
  "locations": [
    {
      "id": "loc_emberhold",
      "name": "Emberhold",
      "description": "The ruined capital built around the Ember Throne, which sits in a hall kept warm by a volcanic vent. Its walls are scarred by three sieges, and the throne room is where the bone-crowns are tested."
    },
    {
      "id": "loc_calderhal_keep",
      "name": "Calderhal Keep",
      "description": "A basalt fortress on the southern cliffs, seat of House Calderhal. Its smiths forge the finest steel in Verrandor and its granaries feed half the war."
    },
    {
      "id": "loc_mireveil_fens",
      "name": "Mireveil Fens",
      "description": "A drowned lowland of black water and lantern-moss, home to House Mireveil. Its people bury their dead in the peat, and the dead are said to answer questions there."
    },
    {
      "id": "loc_orrowyn_heights",
      "name": "Orrowyn Heights",
      "description": "Terraced mountain citadels where House Orrowyn keeps its bell-towers and archives. Messenger hawks and signal bells link its cities faster than any road."
    },
    {
      "id": "loc_glasswound",
      "name": "The Glasswound",
      "description": "A vast northern glacier split by a blue crevasse. Beneath its ice lies the sleeping Hollow Choir, and the ice here hums faintly at night."
    }
  ],
  "factions": [
    {
      "id": "fac_house_calderhal",
      "name": "House Calderhal",
      "description": "A martial dynasty of smiths and knights who believe strength alone proves a ruler's right. They hold the southern cliffs and control the realm's steel.",
      "location_ids": ["loc_calderhal_keep", "loc_emberhold"]
    },
    {
      "id": "fac_house_mireveil",
      "name": "House Mireveil",
      "description": "A secretive line of necromantic diplomats who can speak with the peat-buried dead. They seek the throne by winning the consent of dead kings.",
      "location_ids": ["loc_mireveil_fens"]
    },
    {
      "id": "fac_house_orrowyn",
      "name": "House Orrowyn",
      "description": "Scholarly mountain rulers who control information through bells, hawks and archives. They claim the throne through lawful succession records.",
      "location_ids": ["loc_orrowyn_heights"]
    },
    {
      "id": "fac_frostwardens",
      "name": "The Frostwardens",
      "description": "A neutral order of ice-readers who guard the Glasswound and keep the oldest warnings about the Hollow Choir. Few trust them, and fewer listen.",
      "location_ids": ["loc_glasswound"]
    }
  ],
  "rules": [
    {
      "id": "rul_bone_crowns",
      "statement": "Every crown is forged from the bones of a monarch and retains their memory; a crown rejects any wearer the dead do not accept.",
      "category": "metaphysics"
    },
    {
      "id": "rul_choir_ice",
      "statement": "The Hollow Choir's song causes ice to form and spread; the louder it sings, the faster the ice advances south.",
      "category": "physics"
    },
    {
      "id": "rul_fire_repels",
      "statement": "Volcanic or forge fire slows the Choir's ice, which is why the Ember Throne's vent matters to the whole realm.",
      "category": "physics"
    },
    {
      "id": "rul_peat_dead",
      "statement": "Those buried in Mireveil peat can answer three questions before they fade, and each dead person answers only once.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bell_law",
      "statement": "A decree is legally binding only once it has been rung across three bell-towers; unrung decrees carry no authority.",
      "category": "social"
    },
    {
      "id": "rul_no_black_powder",
      "statement": "Warfare relies on steel, siege-engines, bows and sorcery; no explosive weapons exist in Verrandor.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_last_king_dies",
      "name": "The Last King Falls Silent",
      "description": "King Aldric Veyl died in the Ember Hall without naming an heir, and his bone-crown refused all three claimants.",
      "era": "Year of the Silent Crown",
      "location_ids": ["loc_emberhold"]
    },
    {
      "id": "evt_siege_of_emberhold",
      "name": "The First Siege of Emberhold",
      "description": "House Calderhal stormed the capital but could not hold the throne room, as the throne's warmth failed in their hands.",
      "era": "Year of the Silent Crown",
      "location_ids": ["loc_emberhold", "loc_calderhal_keep"]
    },
    {
      "id": "evt_choir_sealed",
      "name": "The Sealing of the Choir",
      "description": "Ages ago, the first Frostwardens trapped the Hollow Choir beneath the Glasswound using the bones of a sacrificed queen.",
      "era": "Age of Seals",
      "location_ids": ["loc_glasswound"]
    },
    {
      "id": "evt_fens_pact",
      "name": "The Peat Pact",
      "description": "House Mireveil bargained with the dead of the fens for the right to ask them about the realm's lost kings.",
      "era": "Age of Seals",
      "location_ids": ["loc_mireveil_fens"]
    },
    {
      "id": "evt_first_crack",
      "name": "The First Crack in the Ice",
      "description": "A new crevasse opened in the Glasswound and a faint singing was heard from the south for the first time in a thousand years.",
      "era": "Year of the Silent Crown",
      "location_ids": ["loc_glasswound", "loc_orrowyn_heights"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_throne_war",
      "name": "The War of Three Crowns",
      "description": "Calderhal, Mireveil and Orrowyn fight for the Ember Throne by force, by the testimony of the dead, and by law, each undermining the others.",
      "faction_ids": ["fac_house_calderhal", "fac_house_mireveil", "fac_house_orrowyn"]
    },
    {
      "id": "cnf_ignored_warning",
      "name": "The Ignored Warning",
      "description": "The Frostwardens warn that the Choir is waking, but the houses see them as meddlers and refuse to pause the war, even as the ice moves south.",
      "faction_ids": ["fac_frostwardens", "fac_house_calderhal", "fac_house_orrowyn"]
    },
    {
      "id": "cnf_dead_consent",
      "name": "Consent of the Dead",
      "description": "Mireveil's claim that the dead can choose a ruler threatens Calderhal's belief in strength and Orrowyn's faith in written law.",
      "faction_ids": ["fac_house_mireveil", "fac_house_calderhal", "fac_house_orrowyn"]
    }
  ]
}

