response.output:
{
  "world_id": "wld_cabin_signal",
  "name": "The Long Dial",
  "description": "In a pine-locked valley far from any road, Station KDRK broadcasts from a single weathered cabin. Mara Vance, a late-night radio host, begins to receive transmissions in her own voice, recorded days, weeks and finally minutes ahead of the present. The cabin is the entire world of the story. Its transmitter room, its dead-quiet porch and the black treeline beyond the windows are all the space there is. Each message is a warning, and each warning is slightly wrong in a way that costs her something. The tone is slow, creeping dread. Every night the broadcast hours stretch longer and the dark outside the cabin never thins.",
  "locations": [
    {
      "id": "loc_cabin",
      "name": "Kestrel Ridge Cabin",
      "description": "A one-room log cabin with a lean-to transmitter annex, a wood stove and a mast bolted to the roof. The cabin's clocks disagree by a few seconds, and the gap grows through the night. The windows face a treeline that looks no different at any hour. The cabin is the only place where the future transmissions can be heard."
    }
  ],
  "factions": [
    {
      "id": "fac_future_mara",
      "name": "The Echo Voice",
      "description": "The chorus of Mara's own future selves, broadcast from later and later points in her timeline. They agree on almost nothing except that she must keep the cabin transmitter running.",
      "location_ids": ["loc_cabin"]
    },
    {
      "id": "fac_station_owners",
      "name": "Dunmere Broadcasting Trust",
      "description": "The absent corporate owners of KDRK. They pay Mara to keep the signal alive and never explain why the cabin was chosen. Their ledgers show the station has had a host every night for sixty years.",
      "location_ids": ["loc_cabin"]
    },
    {
      "id": "fac_past_hosts",
      "name": "The Unlogged Hosts",
      "description": "Former hosts of the cabin whose voices survive only as gaps in the tape archive. They try to reach Mara through the static to warn her about the price of answering.",
      "location_ids": ["loc_cabin"]
    }
  ],
  "rules": [
    {
      "id": "rul_future_only_on_air",
      "statement": "Future transmissions can only be heard while the cabin transmitter is live and Mara is speaking into the microphone.",
      "category": "technology"
    },
    {
      "id": "rul_memory_toll",
      "statement": "Each time Mara acts on a future message, she permanently forgets one ordinary memory of her past.",
      "category": "metaphysics"
    },
    {
      "id": "rul_shrinking_delay",
      "statement": "The gap between a message being sent and being received shrinks every night, and a message received with no gap fixes the events it describes.",
      "category": "physics"
    },
    {
      "id": "rul_no_outside_signal",
      "statement": "No phone, internet or relay reaches the cabin, and outside contact is possible only by supply drop once a week.",
      "category": "social"
    },
    {
      "id": "rul_perpetual_dark",
      "statement": "Beyond the cabin windows the dark never lifts, and the pine treeline shows no change at any hour.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_station_founding",
      "name": "Founding of KDRK",
      "description": "Dunmere Broadcasting raises the mast on Kestrel Ridge and logs its first overnight host. The cabin is built around the transmitter.",
      "era": "Sixty years ago",
      "location_ids": ["loc_cabin"]
    },
    {
      "id": "evt_first_gap",
      "name": "The First Missing Hour",
      "description": "A tape from the cabin archive is found with a full hour erased and a host who cannot recall her own name. The Trust seals the file.",
      "era": "Thirty years ago",
      "location_ids": ["loc_cabin"]
    },
    {
      "id": "evt_mara_arrives",
      "name": "Mara Takes the Night Shift",
      "description": "Mara Vance moves into the cabin to escape a failed career and hears a faint voice answering her closing sign-off.",
      "era": "Present",
      "location_ids": ["loc_cabin"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_obey_or_silence",
      "name": "Obey the Signal or Go Silent",
      "description": "The Echo Voice demands Mara keep broadcasting so her future can happen, while the Unlogged Hosts urge her to cut the power before the delay reaches zero.",
      "faction_ids": ["fac_future_mara", "fac_past_hosts"]
    },
    {
      "id": "cnf_trust_secret",
      "name": "What the Trust Knows",
      "description": "The Dunmere Broadcasting Trust needs the cabin to stay on air for reasons it hides, and Mara's attempts to shut down the transmitter bring pressure from the Trust and from her own future voice.",
      "faction_ids": ["fac_station_owners", "fac_future_mara"]
    }
  ]
}

